package service

import (
	"os"
	"runtime"
	"strings"

	"github.com/dumanhaydar/rcmanager/internal/rcerr"
)

// OpenRC (Alpine and friends).
//
// OpenRC has no per-user services, so this is a system service that drops to
// the invoking user with command_user. Installing needs root.

func openrcScript(ctx Context) string {
	env := strings.Join(ctx.EnvLines(func(k, v string) string {
		return "export " + k + `="` + v + `"`
	}), "\n")
	if env != "" {
		env += "\n"
	}

	return `#!/sbin/openrc-run
# ` + ctx.Description + `
# Generated by ` + "`rcmanager service install`" + `. Re-run that to refresh it.

name="rcmanager"
description="` + ctx.Description + `"

command="` + ctx.Entrypoint + `"
command_args="daemon --foreground"
command_user="` + ctx.User + `:` + ctx.User + `"
command_background="yes"
directory="` + ctx.Home + `"
pidfile="/run/rcmanager.pid"

output_log="` + ctx.RcmanHome + `/service.log"
error_log="` + ctx.RcmanHome + `/service.log"

export RCMANAGER_HOME="` + ctx.RcmanHome + `"
export HOME="` + ctx.Home + `"
export PATH="` + ctx.Path + `"
` + env + `
respawn_delay=5
respawn_max=0

depend() {
	need net
	after firewall
}
`
}

type openrc struct{}

func init() { register(openrc{}) }

func (openrc) ID() string          { return "openrc" }
func (openrc) DisplayName() string { return "OpenRC" }
func (openrc) Priority() int       { return 50 }

func (openrc) Detect() Availability {
	if runtime.GOOS != "linux" {
		return Availability{false, "OpenRC is Linux-only"}
	}
	if Which("rc-update") == "" || Which("rc-service") == "" {
		return Availability{false, "rc-update/rc-service not found"}
	}
	if os.Geteuid() != 0 && !Exec("sudo", []string{"-n", "true"}, "").OK {
		return Availability{false, "needs root or passwordless sudo"}
	}
	return Availability{true, "OpenRC is available"}
}

func (openrc) UnitPath() string          { return "/etc/init.d/rcmanager" }
func (openrc) Render(ctx Context) string { return openrcScript(ctx) }

func (m openrc) Install(ctx Context) (Installed, error) {
	file := m.UnitPath()
	if write := AsRoot([]string{"tee", file}, openrcScript(ctx)); !write.OK {
		return Installed{}, rcerr.New("could not write "+file+": "+write.Err, "")
	}
	AsRoot([]string{"chmod", "+x", file}, "")

	var notes []string
	if added := AsRoot([]string{"rc-update", "add", "rcmanager", "default"}, ""); !added.OK && added.Err != "" {
		notes = append(notes, added.Err)
	}
	notes = append(notes, "the service runs as "+ctx.User+"; that account must be logged in to the provider CLIs")
	return Installed{Path: file, Notes: notes}, nil
}

func (m openrc) Uninstall() Removed {
	AsRoot([]string{"rc-service", "rcmanager", "stop"}, "")
	AsRoot([]string{"rc-update", "del", "rcmanager", "default"}, "")
	_, err := os.Stat(m.UnitPath())
	existed := err == nil
	AsRoot([]string{"rm", "-f", m.UnitPath()}, "")
	return Removed{Removed: existed}
}

func (m openrc) Status() Status {
	s := Exec("rc-service", []string{"rcmanager", "status"}, "")
	_, err := os.Stat(m.UnitPath())
	return Status{
		Installed: err == nil,
		Running:   strings.Contains(strings.ToLower(s.Out), "started"),
		Enabled:   strings.Contains(Exec("rc-update", []string{"show", "default"}, "").Out, "rcmanager"),
		Detail:    orElse(strings.SplitN(s.Out, "\n", 2)[0], "unknown"),
	}
}

func (openrc) Start() Run       { return AsRoot([]string{"rc-service", "rcmanager", "start"}, "") }
func (openrc) Stop() Run        { return AsRoot([]string{"rc-service", "rcmanager", "stop"}, "") }
func (openrc) LogsHint() string { return `tail -f "$RCMANAGER_HOME/service.log"` }
